css:
:root{
  --bg:#fafaf9; --panel:#fafaf9; --card:#f1f1ef; --ink:#1d2126; --muted:#5d6570;
  --line:#e2e1dd; --accent:#3b6ea5; --accent-ink:#ffffff;
  --ok:#2e7d4f; --ok-bg:#e4f2e9; --warn:#9a6a12; --warn-bg:#f7edd6;
  --bad:#ab3a32; --bad-bg:#f8e5e3; --info:#33608f; --info-bg:#e5edf6;
  --todo:#6d4e9e; --todo-bg:#efe8f8; --code-bg:#ededea;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --bg:#16181c; --panel:#16181c; --card:#1d2025; --ink:#d8dbe0; --muted:#8b939e;
  --line:#2b2f36; --accent:#82aede; --accent-ink:#10141a;
  --ok:#5fbd8a; --ok-bg:#14301f; --warn:#d9ae4b; --warn-bg:#322810;
  --bad:#e08078; --bad-bg:#3a1a17; --info:#8fb4dd; --info-bg:#182636;
  --todo:#b99ae0; --todo-bg:#281b3a; --code-bg:#22262c;
}}
:root[data-theme="dark"]{color-scheme:dark;
  --bg:#16181c; --panel:#16181c; --card:#1d2025; --ink:#d8dbe0; --muted:#8b939e;
  --line:#2b2f36; --accent:#82aede; --accent-ink:#10141a;
  --ok:#5fbd8a; --ok-bg:#14301f; --warn:#d9ae4b; --warn-bg:#322810;
  --bad:#e08078; --bad-bg:#3a1a17; --info:#8fb4dd; --info-bg:#182636;
  --todo:#b99ae0; --todo-bg:#281b3a; --code-bg:#22262c;
}
:root[data-theme="light"]{color-scheme:light;
  --bg:#fafaf9; --panel:#fafaf9; --card:#f1f1ef; --ink:#1d2126; --muted:#5d6570;
  --line:#e2e1dd; --accent:#3b6ea5; --accent-ink:#ffffff;
  --ok:#2e7d4f; --ok-bg:#e4f2e9; --warn:#9a6a12; --warn-bg:#f7edd6;
  --bad:#ab3a32; --bad-bg:#f8e5e3; --info:#33608f; --info-bg:#e5edf6;
  --todo:#6d4e9e; --todo-bg:#efe8f8; --code-bg:#ededea;
}
:root{--fs:17px}
*{box-sizing:border-box}
html{font-size:var(--fs)}
body{margin:0;background:var(--bg);color:var(--ink);
  font:1rem/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}
header.page{position:sticky;top:0;z-index:5;background:var(--bg);
  border-bottom:1px solid var(--line);padding:.65rem 1.2rem;
  display:flex;flex-wrap:wrap;align-items:baseline;gap:.6rem}
header.page h1{font-size:1.22rem;margin:0;font-weight:650}
header.page .spacer{flex:1}
.chip{display:inline-block;padding:.1rem .55rem;border:1px solid var(--line);
  border-radius:99px;font-size:.83rem;color:var(--muted)}
button.theme,button.fs{border:1px solid var(--line);background:var(--bg);color:var(--ink);
  border-radius:.4rem;padding:.18rem .55rem;cursor:pointer;font-size:.83rem}
.layout{display:grid;grid-template-columns:15rem minmax(0,1fr);
  max-width:78rem;margin:0 auto;gap:2rem;padding:1.2rem}
@media(max-width:62rem){.layout{grid-template-columns:minmax(0,1fr)}nav#toc{display:none}}
nav#toc{position:sticky;top:3.6rem;align-self:start;font-size:.88rem;
  padding-right:1rem;max-height:88vh;overflow:auto}
nav#toc a{display:block;color:var(--muted);text-decoration:none;padding:.13rem 0}
nav#toc a.h3{padding-left:.9rem;font-size:.83rem}
nav#toc a:hover{color:var(--accent)}
nav#toc a.on{color:var(--accent);font-weight:600;
  box-shadow:inset .16rem 0 0 var(--accent);padding-left:.35rem}
nav#toc a.h3.on{padding-left:1.25rem}
main{min-width:0;counter-reset:sec}
section{border-top:1px solid var(--line);padding:1.5rem 0 .6rem;margin:0}
section:first-of-type{border-top:none;padding-top:.4rem}
h1,h2,h3{text-wrap:balance}
main section>h2{counter-increment:sec}
main section>h2::before{content:counter(sec) ".  ";color:var(--muted);font-weight:500}
main section#summary>h2::before{content:""}
main section#summary>h2{counter-increment:none}
h2{font-size:1.3rem;margin:.1rem 0 .7rem;line-height:1.3}
h3{font-size:1.05rem;margin:1.2rem 0 .45rem;line-height:1.35}
p,ul,ol{margin:.5rem 0;max-width:76ch}
li{margin:.18rem 0}
a{color:var(--accent)}
code,kbd{background:var(--code-bg);border-radius:.3rem;padding:.06rem .32rem;
  font:.88em ui-monospace,SFMono-Regular,Menlo,monospace}
pre{background:var(--code-bg);padding:.7rem .9rem;border-radius:.45rem;
  overflow-x:auto;font-size:.9rem;line-height:1.5}
pre code{background:none;padding:0;font-size:1em}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(9.5rem,1fr));
  gap:.6rem;margin:.5rem 0 1rem}
.tile{border:1px solid var(--line);border-radius:.45rem;padding:.5rem .75rem;background:var(--card)}
.tile .n{font-size:1.45rem;font-weight:650;display:block;line-height:1.25;
  font-variant-numeric:tabular-nums}
.tile .l{font-size:.82rem;color:var(--muted)}
.tile.qa{position:relative;cursor:help}
.tile.qa::after{content:"⌕";position:absolute;top:.3rem;right:.45rem;opacity:.35;font-size:.8rem}
.badge{display:inline-block;font-size:.78rem;font-weight:600;letter-spacing:.02em;
  padding:.08rem .5rem;border-radius:99px;white-space:nowrap}
.ok{color:var(--ok);background:var(--ok-bg)} .warn{color:var(--warn);background:var(--warn-bg)}
.bad{color:var(--bad);background:var(--bad-bg)} .info{color:var(--info);background:var(--info-bg)}
.todo{color:var(--todo);background:var(--todo-bg)}
.tablewrap{overflow-x:auto}
table{border-collapse:collapse;width:100%;font-size:.92rem}
th,td{border-bottom:1px solid var(--line);text-align:left;padding:.38rem .55rem;vertical-align:top}
th{color:var(--muted);font-size:.78rem;text-transform:uppercase;letter-spacing:.05em;
  cursor:pointer;user-select:none;white-space:nowrap;font-weight:600}
th.nosort{cursor:default}
td.num,td[data-v]{text-align:right;font-variant-numeric:tabular-nums}
tr:hover td{background:color-mix(in srgb, var(--accent) 6%, transparent)}
details{border:1px solid var(--line);border-radius:.45rem;padding:.5rem .85rem;margin:.55rem 0;background:var(--card)}
summary{cursor:pointer;font-weight:600;font-size:.97rem}
details[open]{padding-bottom:.6rem}
input.filter{width:100%;max-width:26rem;margin:.2rem 0 .55rem;padding:.32rem .6rem;
  border:1px solid var(--line);border-radius:.4rem;background:var(--bg);color:var(--ink);
  font-size:.93rem}
footer{color:var(--muted);font-size:.85rem;text-align:center;padding:1.2rem;max-width:76rem;margin:0 auto}
dl.gloss{display:grid;grid-template-columns:auto 1fr;gap:.25rem 1.1rem;font-size:.95rem;max-width:none}
dl.gloss dt{font-weight:600;white-space:nowrap;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88rem}
dl.gloss dd{margin:0;max-width:66ch}
.meta{display:grid;grid-template-columns:auto 1fr;gap:.2rem .9rem;font-size:.9rem;
  border-left:3px solid var(--line);padding:.1rem 0 .1rem .9rem;margin:.2rem 0 .9rem}
.meta dt{color:var(--muted)}
.meta dd{margin:0}
.ev{display:inline-block;font-size:.7rem;font-weight:700;letter-spacing:.03em;
  padding:0 .35rem;border-radius:.25rem;vertical-align:.1em;text-transform:uppercase}
.ev-measured{color:var(--ok);background:var(--ok-bg)}
.ev-derived{color:var(--info);background:var(--info-bg)}
.ev-inferred{color:var(--warn);background:var(--warn-bg)}
.ev-assumed{color:var(--bad);background:var(--bad-bg)}
.claim{border-radius:.25rem;padding:.02rem .2rem;
  box-decoration-break:clone;-webkit-box-decoration-break:clone}
.claim>.ev{margin-left:.28em}
.claim-m{background:color-mix(in srgb,var(--ok) 10%,transparent);
  box-shadow:inset 0 -2px 0 color-mix(in srgb,var(--ok) 45%,transparent)}
.claim-d{background:color-mix(in srgb,var(--info) 10%,transparent);
  box-shadow:inset 0 -2px 0 color-mix(in srgb,var(--info) 45%,transparent)}
.claim-i{background:color-mix(in srgb,var(--warn) 10%,transparent);
  box-shadow:inset 0 -2px 0 color-mix(in srgb,var(--warn) 45%,transparent)}
time.age{color:var(--muted);font-size:.85em;font-variant-numeric:tabular-nums}
time.age.stale{color:var(--warn);font-weight:600}
time.age.stale::after{content:" ⚠"}
a.path{font:.88em ui-monospace,SFMono-Regular,Menlo,monospace;background:var(--code-bg);
  border-radius:.3rem;padding:.06rem .32rem;text-decoration:none;
  border-bottom:1px dotted var(--accent)}
a.path::after{content:"↗";font-size:.75em;color:var(--muted);margin-left:.15rem}
a.path.haspop::after{content:"⧉";color:var(--accent)}
.pop{position:fixed;z-index:50;max-width:min(46rem,92vw);max-height:70vh;overflow:auto;
  background:var(--bg);border:1px solid var(--line);border-radius:.5rem;
  box-shadow:0 .6rem 2rem rgba(0,0,0,.28);padding:.7rem .9rem;font-size:.92rem}
.pop h4{margin:0 0 .35rem;font-size:.92rem;font-family:ui-monospace,monospace;color:var(--muted)}
.pop pre{margin:0;max-height:52vh;font-size:.85rem}
.pop .pin{float:right;border:none;background:none;color:var(--muted);cursor:pointer}
@media(hover:none){.pop{max-width:94vw}}
figure.code{margin:.7rem 0;border:1px solid var(--line);border-radius:.45rem;overflow:hidden;max-width:84ch}
figure.code figcaption{display:flex;gap:.5rem;align-items:center;background:var(--card);
  border-bottom:1px solid var(--line);padding:.28rem .7rem;font:.83rem ui-monospace,monospace;
  color:var(--muted)}
figure.code figcaption .lang{font-weight:700;letter-spacing:.03em;color:var(--accent);
  text-transform:uppercase;font-size:.7rem}
figure.code figcaption .sp{flex:1}
figure.code pre{margin:0;border-radius:0;tab-size:4}
.iq{font-style:italic;background:color-mix(in srgb,var(--accent) 8%,transparent);
  padding:.02rem .3rem;border-radius:.2rem;box-decoration-break:clone}
svg text{font-family:system-ui,sans-serif}
.bar{display:flex;align-items:center;gap:.5rem;margin:.12rem 0}
.bar .lab{width:6.5rem;font-size:.84rem;color:var(--muted);text-align:right;
  font-variant-numeric:tabular-nums;flex-shrink:0}
.bar .trk{flex:1;background:var(--card);border-radius:.2rem;height:.8rem;position:relative;max-width:30rem}
.bar .fil{position:absolute;inset:0 auto 0 0;background:var(--accent);border-radius:.2rem;opacity:.75}
.bar .val{font-size:.82rem;font-variant-numeric:tabular-nums;color:var(--muted);flex-shrink:0}
.calstrip{display:flex;flex-wrap:wrap;gap:.22rem;margin:.4rem 0}
.cd{width:2.05rem;height:1.7rem;border-radius:.22rem;display:flex;align-items:flex-end;
  justify-content:center;border:1px solid var(--line)}
.cd span{font-size:.62rem;color:var(--muted);line-height:1.5}

.hole{color:var(--warn);font-size:.9rem}

